'use strict';
// Preview checkout only. No card data or live cryptocurrency destination is collected.
const paymentNetworks=[{id:'usdt-trc20',asset:'USDT',network:'TRC20',name:'Tron'},{id:'usdt-erc20',asset:'USDT',network:'ERC20',name:'Ethereum'},{id:'usdc-base',asset:'USDC',network:'Base',name:'Base'},{id:'btc',asset:'BTC',network:'Bitcoin',name:'Bitcoin'}];
let paymentDraft=null;
const paymentBeforeMethods=paymentModal;
const paymentNetwork=()=>paymentNetworks.find(n=>n.id===paymentDraft?.network)||paymentNetworks[0];
const paymentLabel=r=>r.payment?.method==='card'?'Card':r.payment?.method==='crypto'?`${r.payment.asset} · ${r.payment.network}`:'Funding request';
const paymentValid=n=>Number.isFinite(n)&&n>=1&&n<=100000&&Math.abs(n*100-Math.round(n*100))<.00001;
function paymentModalHeader(title){return `<div class="payment-header"><span class="j-eyebrow">ECO CHARGE / PAYMENT</span><span class="payment-preview-label">Payment preview</span></div><h2>${title}</h2>`;}
paymentModal=function(type){if(type!=='topup')return paymentBeforeMethods(type);paymentDraft={id:'PAY-'+crypto.randomUUID().slice(0,12).toUpperCase(),amount:draftFundingGap()||250,method:'card',network:'usdt-trc20',step:'choose'};showPaymentMethods();};
function showPaymentMethods(){if(!paymentDraft)return;paymentDraft.step='choose';openModal(`${paymentModalHeader('Choose how to add funds')}<p>Your payment method, amount and request status stay together in your account.</p><form id="funding-method-form"><label for="payment-amount">Amount (USD)</label><input id="payment-amount" type="number" inputmode="decimal" min="1" max="100000" step=".01" value="${paymentDraft.amount}" required><div class="quick-amounts">${[250,500,1000].map(n=>`<button type="button" data-amount="${n}">${money(n)}</button>`).join('')}</div><fieldset class="payment-methods"><legend>Payment method</legend><label><input type="radio" name="payment-method" value="card" ${paymentDraft.method==='card'?'checked':''}><span>${icon('assets')}<strong>Debit or credit card</strong><small>A separate card checkout</small></span></label><label><input type="radio" name="payment-method" value="crypto" ${paymentDraft.method==='crypto'?'checked':''}><span>${icon('zap')}<strong>Cryptocurrency</strong><small>QR code or wallet address</small></span></label></fieldset><div class="payment-network-choice" ${paymentDraft.method==='crypto'?'':'hidden'}><label for="funding-network">Asset and network</label><select id="funding-network">${paymentNetworks.map(n=>`<option value="${n.id}" ${n.id===paymentDraft.network?'selected':''}>${n.asset} · ${n.network} (${n.name})</option>`).join('')}</select><small>Always match the asset and network shown on the payment request.</small></div><p class="modal-note">Preview only. No card is charged and no live receiving wallet is connected.</p><div id="funding-error" class="form-error" role="alert"></div><button class="button primary" type="submit">Continue to payment ${icon('arrow')}</button></form>`);}
function showCardCheckout(){if(!paymentDraft)return;paymentDraft.step='card';openModal(`${paymentModalHeader('Card payment')}<div class="payment-total"><span>Amount to add</span><strong>${money(paymentDraft.amount)}</strong></div><div class="payment-card-preview"><div><strong>ECO CHARGE</strong><span>TEST CARD</span></div><b translate="no">•••• •••• •••• 4242</b><small>No real card details are needed</small></div><p class="modal-note">This previews a separate provider checkout. Card numbers and security codes are not entered or stored on this site.</p><div id="payment-checkout-error" class="form-error" role="alert"></div><button class="button primary" data-action="submit-card-payment">Submit card payment request ${icon('arrow')}</button><div class="payment-secondary-actions"><button class="text-button" data-action="payment-declined">Try a declined payment</button><button class="text-button" data-action="payment-back">Change payment method</button></div><p class="payment-fineprint">The balance changes only after the manager approves the request.</p>`);}
function paymentPreviewAddress(){return 'PREVIEW-NO-LIVE-WALLET-'+paymentNetwork().id.toUpperCase();}
function paymentQrPayload(){return JSON.stringify({type:'ecocharge-payment-preview',id:paymentDraft.id,amountUSD:paymentDraft.amount,asset:paymentNetwork().asset,network:paymentNetwork().network,transferEnabled:false});}
async function renderPaymentQr(){const target=$('#payment-qr');if(!target||!paymentDraft)return;const expected=paymentQrPayload();try{await window.ecoLoadLibrary('qr');if(!target.isConnected||!paymentDraft||expected!==paymentQrPayload())return;const qr=qrcode(0,'M');qr.addData(expected,'Byte');qr.make();target.innerHTML=qr.createSvgTag({cellSize:4,margin:16,scalable:true});target.dataset.payload=expected;const svg=target.querySelector('svg');svg.setAttribute('role','img');svg.setAttribute('aria-label','Payment preview QR code');window.EcoLocale?.localize(target);}catch{if(target.isConnected)target.innerHTML='<button type="button" class="text-button" data-action="payment-qr-retry">QR could not load. Try again.</button>';}}
function showCryptoCheckout(){if(!paymentDraft)return;paymentDraft.step='crypto';const n=paymentNetwork();openModal(`${paymentModalHeader('Crypto payment')}<div class="payment-total"><span>Amount to add</span><strong>${money(paymentDraft.amount)}</strong></div><label for="checkout-network">Asset and network</label><select id="checkout-network">${paymentNetworks.map(v=>`<option value="${v.id}" ${v.id===n.id?'selected':''}>${v.asset} · ${v.network} (${v.name})</option>`).join('')}</select><div class="payment-crypto"><div class="payment-qr-wrap"><div id="payment-qr" aria-busy="false"><span>Preparing QR code…</span></div><small>Preview QR · no transfer destination</small></div><div class="payment-wallet"><span class="payment-network-badge" translate="no">${n.asset} / ${n.network}</span><label for="payment-address">Wallet address preview</label><textarea id="payment-address" rows="3" readonly spellcheck="false" translate="no">${paymentPreviewAddress()}</textarea><button class="button secondary" data-action="copy-payment-address">Copy address ${icon('file')}</button><small>Use only the selected network. A live address will be supplied by the payment provider.</small></div></div><p class="modal-note">No live wallet is connected. This QR code contains a preview request, not payment instructions. The crypto amount and network fee require a live quote.</p><div id="payment-checkout-error" class="form-error" role="alert"></div><button class="button primary" data-action="submit-crypto-payment">Submit crypto payment request ${icon('arrow')}</button><button class="text-button payment-back" data-action="payment-back">Change payment method</button><p class="payment-fineprint">The balance changes only after the manager approves the request.</p>`);renderPaymentQr();}
function submitPaymentRequest(method){if(!paymentDraft||paymentDraft.step!==method||paymentDraft.method!==method||!paymentValid(paymentDraft.amount))return;const draft={...paymentDraft},n=paymentNetwork();if(demo.requests.some(r=>r.id===draft.id))return;const payment=method==='card'?{mode:'preview',method:'card',currency:'USD',last4:'4242'}:{mode:'preview',method:'crypto',asset:n.asset,network:n.network,networkId:n.id};demo.requests.push({id:draft.id,type:'topup',amount:Math.round(draft.amount*100)/100,status:'Pending',date:new Date().toISOString(),payment});activity('Client submitted payment request: '+money(draft.amount));persist();paymentDraft=null;openModal(`${paymentModalHeader('Payment request sent')}<div class="payment-receipt"><div><span>Request</span><strong translate="no">${draft.id}</strong></div><div><span>Amount</span><strong>${money(draft.amount)}</strong></div><div><span>Payment method</span><strong>${escapeHtml(paymentLabel({payment}))}</strong></div><div><span>Status</span><strong>Awaiting manager review</strong></div></div><p>The request has been saved. Your balance has not changed yet. Your manager can approve or decline it in the team workspace.</p><button class="button primary" data-action="history">View request status ${icon('arrow')}</button><button class="button secondary" data-action="back-overview">Back to overview</button>`);}
actions['payment-back']=showPaymentMethods;
actions['submit-card-payment']=()=>submitPaymentRequest('card');
actions['submit-crypto-payment']=()=>submitPaymentRequest('crypto');
actions['payment-declined']=()=>{$('#payment-checkout-error').textContent='This test payment was declined. No request or charge was created. Try again or choose another payment method.';};
actions['payment-qr-retry']=renderPaymentQr;
actions['copy-payment-address']=async()=>{const input=$('#payment-address');if(!input)return;try{await navigator.clipboard.writeText(input.value);toast('Preview address copied. Do not send funds to it.')}catch{input.focus();input.select();toast('Select and copy the preview address. No live wallet is connected.')}};
document.addEventListener('change',e=>{if(!paymentDraft)return;if(e.target.name==='payment-method'){paymentDraft.method=e.target.value;$('.payment-network-choice').hidden=e.target.value!=='crypto';}if(e.target.id==='funding-network')paymentDraft.network=e.target.value;if(e.target.id==='checkout-network'&&paymentNetworks.some(n=>n.id===e.target.value)){paymentDraft.network=e.target.value;showCryptoCheckout();}});
document.addEventListener('submit',e=>{if(e.target.id!=='funding-method-form')return;e.preventDefault();if(!paymentDraft)return;const amount=Number($('#payment-amount').value);if(!paymentValid(amount)){$('#funding-error').textContent='Enter an amount from $1 to $100,000, with at most two decimal places.';return}paymentDraft.amount=amount;paymentDraft.method=e.target.elements.namedItem('payment-method').value;paymentDraft.network=$('#funding-network').value;paymentDraft.method==='card'?showCardCheckout():showCryptoCheckout();});
const historyBeforePayments=actions.history;
actions.history=()=>{historyBeforePayments();const rows=demo.requests.filter(r=>r.payment).slice().reverse().slice(0,8);if(rows.length)$('#modal-content').insertAdjacentHTML('beforeend',`<section class="payment-history"><h3>Payment methods & status</h3>${rows.map(r=>`<div><span><strong>${escapeHtml(paymentLabel(r))}</strong><small translate="no">${escapeHtml(r.id)}</small></span><span><strong>${money(r.amount)}</strong><small>${escapeHtml(r.status)}</small></span></div>`).join('')}</section>`);};
const reviewBeforePayments=reviewRequest;
reviewRequest=function(id,decision){reviewBeforePayments(id,decision);const r=demo.requests.find(r=>r.id===id);if(r?.payment&&$('#review-form'))$('#review-form').insertAdjacentHTML('beforebegin',`<div class="payment-review"><span>Payment method</span><strong>${escapeHtml(paymentLabel(r))}</strong><p>Preview request. Approval changes the sample balance; it does not verify a card charge or a blockchain transfer.</p></div>`);};
const acquisitionRoutes=[['website','Website → account'],['lead-form','Lead form → caller → account']];
const acquisitionStages=[['new','New lead'],['contacted','Contacted by caller'],['qualified','Qualified'],['payment','Payment discussed']];
function acquisitionDetails(){const a=demo.acquisition||{},funded=demo.requests.some(r=>r.type==='topup'&&r.status==='Approved'),pending=demo.requests.some(r=>r.type==='topup'&&r.status==='Pending');return {route:acquisitionRoutes.find(r=>r[0]===(a.route||demo.attribution?.lead_route))?.[1]||'Not recorded',stage:funded?'First deposit recorded':pending?'Payment awaiting review':acquisitionStages.find(s=>s[0]===a.stage)?.[1]||'New lead'};}
const profileBeforePayments=cabProfile;
cabProfile=function(){const a=acquisitionDetails();return profileBeforePayments()+`<section class="cab-card-section"><div class="cab-section-heading"><h2>Acquisition & payment</h2><button class="button secondary" data-action="edit-acquisition">Edit lead details</button></div><dl class="cab-detail-list"><div><dt>Entry path</dt><dd>${a.route}</dd></div><div><dt>Lead stage</dt><dd>${a.stage}</dd></div><div><dt>Phone</dt><dd translate="no">${escapeHtml(demo.acquisition?.phone||'—')}</dd></div></dl><p class="cab-caption">Lead details are managed in this workspace. Meta lead forms and a shared CRM are not connected.</p></section>`;};
actions['edit-acquisition']=()=>{if(role!=='admin')return;const a=demo.acquisition||{};openModal(`<h2>Lead details</h2><form id="acquisition-form"><label for="acquisition-route">Entry path</label><select id="acquisition-route">${acquisitionRoutes.map(([id,label])=>`<option value="${id}" ${(a.route||demo.attribution?.lead_route)===id?'selected':''}>${label}</option>`).join('')}</select><label for="acquisition-stage">Lead stage</label><select id="acquisition-stage">${acquisitionStages.map(([id,label])=>`<option value="${id}" ${a.stage===id?'selected':''}>${label}</option>`).join('')}</select><label for="acquisition-phone">Phone</label><input id="acquisition-phone" type="tel" maxlength="40" autocomplete="off" value="${escapeHtml(a.phone||'')}" placeholder="+1 555 010 0000"><p class="form-hint">Payment status updates from funding requests. These fields do not send a message or place a call.</p><button class="button primary" type="submit">Save lead details</button></form>`);};
document.addEventListener('submit',e=>{if(e.target.id!=='acquisition-form')return;e.preventDefault();if(role!=='admin')return;const route=$('#acquisition-route').value,stage=$('#acquisition-stage').value;if(!acquisitionRoutes.some(r=>r[0]===route)||!acquisitionStages.some(s=>s[0]===stage))return;demo.acquisition={route,stage,phone:$('#acquisition-phone').value.trim(),updatedAt:new Date().toISOString()};activity('Manager updated lead details');persist();$('#modal').close();renderAdmin();toast('Lead details saved.');});

// Preserve an explicit lead-form route or first-touch campaign for direct account visits.
try{const params=new URL(location.href).searchParams,context=JSON.parse(sessionStorage.getItem('ecocharge-attribution')||'{}');for(const key of ['utm_source','utm_medium','utm_campaign','utm_content','utm_term','gclid','fbclid'])if(params.has(key)&&!context[key])context[key]=params.get(key).slice(0,300);if(['website','lead-form'].includes(params.get('lead_route')))context.lead_route=params.get('lead_route');if(Object.keys(context).length&&!demo.attribution){demo.attribution=context;persist();}}catch{}
